import { spawn } from 'node:child_process';
import path from 'node:path';
import { SourceLocation, SourcePosition } from '@moderado/contracts';
import { resolveInJail } from './jail.js';
import { getSanitizedEnv } from './tools/run_command.js';

export async function requestLanguageServer(root:string, executable:string, method:'textDocument/definition'|'textDocument/references', position:SourcePosition):Promise<SourceLocation[]> {
  const file=resolveInJail(root,position.path); const uri=new URL(`file:///${file.replace(/\\/g,'/')}`).href;
  return new Promise((resolve,reject)=>{const child=spawn(executable,['--stdio'],{cwd:resolveInJail(root,'.'),env:getSanitizedEnv(),shell:false,windowsHide:true});let buffer='';let done=false;const finish=(value:SourceLocation[]|Error)=>{if(done)return;done=true;clearTimeout(timer);child.kill();value instanceof Error?reject(value):resolve(value);};const send=(body:Record<string, unknown>)=>{const text=JSON.stringify({jsonrpc:'2.0',...body});child.stdin?.write(`Content-Length: ${Buffer.byteLength(text)}\r\n\r\n${text}`);}; const timer=setTimeout(()=>finish(new Error('TypeScript language server timed out. Configure typescriptLanguageServer or install typescript-language-server.')),10000);child.on('error',()=>finish(new Error(`Unable to start TypeScript language server '${executable}'. Install it and configure typescriptLanguageServer.`))); child.stdout?.on('data',(chunk:Buffer)=>{buffer+=chunk.toString();if(buffer.length>1048576)return finish(new Error('Language server response exceeded 1 MB.'));let split;while((split=buffer.indexOf('\r\n\r\n'))>=0){const header=buffer.slice(0,split);const m=header.match(/Content-Length:\s*(\d+)/i);if(!m)return finish(new Error('Malformed language server response.'));const end=split+4+Number(m[1]);if(buffer.length<end)return;const text=buffer.slice(split+4,end);buffer=buffer.slice(end);let msg:any;try{msg=JSON.parse(text);}catch{return finish(new Error('Malformed language server JSON response.'));}if(msg.id===3){const raw=Array.isArray(msg.result)?msg.result:msg.result?[msg.result]:[];const locations:SourceLocation[]=[];for(const item of raw){try{const target=new URL(item.uri??item.targetUri);const targetFile=resolveInJail(root,decodeURIComponent(target.pathname));const range=item.range??item.targetSelectionRange;locations.push({path:path.relative(resolveInJail(root,'.'),targetFile).split(path.sep).join('/'),line:range.start.line+1,column:range.start.character+1,endLine:range.end.line+1,endColumn:range.end.character+1});}catch{}}finish(locations);}}});send({id:1,method:'initialize',params:{processId:process.pid,rootUri:new URL(`file:///${resolveInJail(root,'.').replace(/\\/g,'/')}`).href,capabilities:{}}});send({method:'initialized',params:{}});send({method:'textDocument/didOpen',params:{textDocument:{uri,languageId:'typescript',version:1,text:require('node:fs').readFileSync(file,'utf8')}}});send({id:3,method,params:{textDocument:{uri},position:{line:position.line-1,character:position.column-1},...(method.endsWith('references')?{context:{includeDeclaration:true}}:{})}});});
}